    "fullSolution": "\"\"\"Exercise 00-foundations.T1.00a - reference solution.\n\nThe Python a robot script is built from before any hardware exists: a variable updated from the\nright-hand side, a `while` loop that steps time forward, a `for` loop over `range(n)`, a one-sided\nclamp, a function that catches a traceback's exception and reports its type, and the three-decimal\nformat the worked example prints.\n\"\"\"\n\n\ndef step_position(pos_m, vel_m_s, dt_s):\n    \"\"\"x_next = x + v * dt. Negative time would run the simulator backwards.\"\"\"\n    if dt_s < 0.0:\n        raise ValueError(\"time only runs forwards in this simulator\")\n    return pos_m + vel_m_s * dt_s\n\n\ndef steps_to_target(pos_0, vel_m_s, dt_s, target_m):\n    \"\"\"How many ticks of the loop the worked example takes to reach target_m.\"\"\"\n    if dt_s <= 0.0:\n        raise ValueError(\"a zero time step never advances the position\")\n    if vel_m_s <= 0.0:\n        raise ValueError(\"a robot that is not moving forward never reaches the target\")\n    steps = 0\n    pos_m = pos_0\n    while pos_m < target_m - 1e-9:\n        pos_m = step_position(pos_m, vel_m_s, dt_s)\n        steps += 1\n    return steps\n\n\ndef battery_voltage_after_steps(v_start, drop_per_step, n_steps):\n    \"\"\"Subtract drop_per_step from v_start exactly n_steps times - range(n) has n terms.\"\"\"\n    if n_steps < 0:\n        raise ValueError(\"a loop cannot run a negative number of times\")\n    v_now = v_start\n    for _step in range(n_steps):\n        v_now -= drop_per_step\n    return v_now\n\n\ndef loop_total(n_steps):\n    \"\"\"The Skip test's accumulator: sum of i*2 for i in range(n_steps).\"\"\"\n    if n_steps < 0:\n        raise ValueError(\"a loop cannot run a negative number of times\")\n    total = 0\n    for i in range(n_steps):\n        total += i * 2\n    return total\n\n\ndef clamp_pwm(u, u_max):\n    \"\"\"One-sided ceiling: u_max when u is above it, u itself otherwise.\"\"\"\n    if u_max <= 0.0:\n        raise ValueError(\"a PWM ceiling must be positive\")\n    return u_max if u > u_max else u\n\n\ndef safe_divide(numerator, denominator):\n    \"\"\"Return (value, error_name) - a clean division reports an empty name.\"\"\"\n    try:\n        return numerator / denominator, \"\"\n    except ZeroDivisionError as exc:\n        return None, type(exc).__name__\n\n\ndef format_position(pos_m):\n    \"\"\"The worked example's `{pos_m:.3f}` field, on its own.\"\"\"\n    return f\"{pos_m:.3f}\"\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 00-foundations.T1.00a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(step_position(0.0, 0.5, 0.25) - 0.125) < 1e-12, \"one 0.25 s tick\"\n    assert abs(step_position(0.25, 0.5, 0.25) - 0.375) < 1e-12, \"right-hand side first\"\n    assert steps_to_target(0.0, 0.5, 0.25, 1.0) == 8, \"eight ticks to 1.0 m\"\n    checks += 1\n\n    assert abs(battery_voltage_after_steps(12.0, 0.15, 10) - 10.5) < 1e-6, \"ten drops\"\n    assert abs(battery_voltage_after_steps(12.0, 0.15, 0) - 12.0) < 1e-12, \"range(0)\"\n    checks += 1\n\n    assert loop_total(4) == 12, \"0 + 2 + 4 + 6\"\n    assert loop_total(0) == 0, \"an empty range\"\n    assert clamp_pwm(1.35, 1.0) == 1.0, \"the skip test's clamp\"\n    assert clamp_pwm(0.40, 1.0) == 0.40, \"inside the ceiling\"\n    checks += 1\n\n    assert safe_divide(1.0, 0.0) == (None, \"ZeroDivisionError\"), \"the caught exception's name\"\n    assert safe_divide(1.0, 0.25) == (4.0, \"\"), \"a clean division\"\n    assert format_position(1.0) == \"1.000\", \"three decimals\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the position update and its step count, the battery sag \"\n          \"over range(n), the Skip test's accumulator and clamp, the caught exception's name and \"\n          \"the three-decimal format\" % checks)\n\n\n_selfcheck()\n",
