    "starterCode": "\"\"\"Exercise 00-foundations.T1.00b - the learner's file.\n\nA recorded window, a scaled sensor trace, the two summary statistics, the per-sample tracking\nerror with its RMS, and the Git command behind a task. Fill the seven TODOs:\n\n    EXERCISE_TARGET=exercises/00-foundations.T1.00b/starter.py \\\n        python3 -m unittest discover -s exercises/00-foundations.T1.00b -p 'test_*.py'\n\"\"\"\n\nimport math\n\n\ndef timestamps(t0_s, dt_s, n):\n    \"\"\"t_i = t0 + i*dt for i = 0 .. n-1.\"\"\"\n    raise NotImplementedError(\"TODO 1: start at i = 0, so the last index is n - 1\")\n\n\ndef scaled_readings(values, config):\n    \"\"\"y_i = slope * x_i + offset, both constants looked up by name.\"\"\"\n    raise NotImplementedError(\"TODO 2: read config['slope'] and config['offset'], then m*x + b\")\n\n\ndef mean_of(values):\n    \"\"\"The sample mean.\"\"\"\n    raise NotImplementedError(\"TODO 3: sum the values, then divide by how many there are\")\n\n\ndef peak_to_peak(values):\n    \"\"\"max - min, the span a plot has to cover.\"\"\"\n    raise NotImplementedError(\"TODO 4: the span is a MAXIMUM minus a MINIMUM, not a half-span\")\n\n\ndef errors(target, measured):\n    \"\"\"e_i = target_i - measured_i, paired by zip().\"\"\"\n    raise NotImplementedError(\"TODO 5: target minus measured, sample by sample, same length\")\n\n\ndef rmse(target, measured):\n    \"\"\"sqrt(mean(e_i^2)).\"\"\"\n    raise NotImplementedError(\"TODO 6: SQUARE each error before averaging - signed errors cancel\")\n\n\ndef git_command(task):\n    \"\"\"The command for a task.\"\"\"\n    raise NotImplementedError(\"TODO 7: a dictionary lookup by task name, and refuse a miss\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 00-foundations.T1.00b.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, constant time,\none PASS line.\n\"\"\"\n\n\ndef _selfcheck():\n    checks = 0\n\n    window = timestamps(0.0, 0.1, 5)\n    assert len(window) == 5, \"five samples in, five timestamps out\"\n    assert abs(window[-1] - 0.4) < 1e-12, \"the last index is n - 1, not n\"\n    assert abs(timestamps(0.0, 0.002, 501)[500] - 1.0) < 1e-12, \"2 ms grid, sample 500\"\n    checks += 1\n\n    trace = scaled_readings([0.0, 0.1, 0.2, 0.3, 0.4], {\"slope\": 3.0, \"offset\": 0.5})\n    assert abs(trace[0] - 0.5) < 1e-12 and abs(trace[-1] - 1.7) < 1e-12, \"the worked trace\"\n    assert abs(mean_of(trace) - 1.10) < 1e-12, \"worked mean\"\n    assert abs(peak_to_peak(trace) - 1.20) < 1e-12, \"worked span, max minus min\"\n    checks += 1\n\n    err = errors([1.0, 2.0, 3.0, 4.0], [0.9, 2.1, 2.8, 4.2])\n    assert abs(sum(err)) < 1e-12, \"the signed errors cancel to zero\"\n    assert abs(rmse([1.0, 2.0, 3.0, 4.0], [0.9, 2.1, 2.8, 4.2]) - 0.1581139) < 1e-6, \"sqrt(0.025)\"\n    checks += 1\n\n    assert git_command(\"which lines changed\") == \"git diff\", \"the Skip test's answer\"\n    assert git_command(\"which files changed\") == \"git status\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the zero-indexed timestamp grid, the dictionary-calibrated \"\n          \"trace with its mean and peak-to-peak span, the zip()-paired error list with a squared \"\n          \"RMS, and the Git command lookup\" % checks)\n\n\n_selfcheck()\n",
