    "fullSolution": "\"\"\"Exercise 00-foundations.T2.00b - reference solution.\n\nThe three operations are the same one seen three ways: a dot product is a projection onto a\ndirection, a cross product is the area of the parallelogram the two vectors span (with a direction),\nand a 2x2 determinant is that same signed area in the plane. A basis is invertible exactly when that\narea is not zero - which is why a singular arm pose and a collinear pair of basis vectors fail the\nsame test.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef dot3(a, b):\n    \"\"\"The 3D dot product.\"\"\"\n    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]\n\n\ndef cross3(a, b):\n    \"\"\"The 3D cross product a x b.\"\"\"\n    return [\n        a[1] * b[2] - a[2] * b[1],\n        a[2] * b[0] - a[0] * b[2],\n        a[0] * b[1] - a[1] * b[0],\n    ]\n\n\ndef axial_force(force, lever):\n    \"\"\"Component of `force` along the lever's unit direction, N.\"\"\"\n    length = math.sqrt(dot3(lever, lever))\n    if length == 0.0:\n        raise ValueError(\"a zero-length lever has no direction to project onto\")\n    return dot3(force, [component / length for component in lever])\n\n\ndef moment(lever, force):\n    \"\"\"r x F, N*m.\"\"\"\n    return cross3(lever, force)\n\n\ndef det2(b1, b2):\n    \"\"\"Signed area of the parallelogram spanned by b1 and b2.\"\"\"\n    return b1[0] * b2[1] - b2[0] * b1[1]\n\n\ndef coordinates_in_basis(vector, b1, b2):\n    \"\"\"(c1, c2) with c1*b1 + c2*b2 == vector, or ValueError when the basis is singular.\"\"\"\n    det = det2(b1, b2)\n    if abs(det) < 1e-12:\n        raise ValueError(\"basis is singular: det = %.3e, the two directions are collinear\" % det)\n    c1 = (vector[0] * b2[1] - b2[0] * vector[1]) / det\n    c2 = (b1[0] * vector[1] - vector[0] * b1[1]) / det\n    return c1, c2\n\n\ndef in_basis(vector, b1, b2):\n    \"\"\"Rebuild the vector from its coordinates.\"\"\"\n    c1, c2 = coordinates_in_basis(vector, b1, b2)\n    return [c1 * b1[0] + c2 * b2[0], c1 * b1[1] + c2 * b2[1]]\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 00-foundations.T2.00b.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only (`math` + the\nplant), one PASS line, because the browser grades on stdout.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef _selfcheck():\n    checks = 0\n    force = [0.0, -20.0, 15.0]\n    lever = [0.30, 0.40, 0.00]\n\n    assert abs(axial_force(force, lever) + 16.0) < 1e-9, \"worked projection\"\n    assert abs(axial_force(force, [3.0, 4.0, 0.0]) + 16.0) < 1e-9, \"projection must not scale with lever length\"\n    checks += 1\n\n    tau = moment(lever, force)\n    for got, want in zip(tau, [6.0, -4.5, -6.0]):\n        assert abs(got - want) < 1e-9, \"worked moment\"\n    assert abs(dot3(tau, lever)) < 1e-12, \"moment is orthogonal to the lever\"\n    back = cross3(force, lever)\n    for got, want in zip(tau, back):\n        assert abs(got + want) < 1e-12, \"cross product is antisymmetric\"\n    checks += 1\n\n    assert abs(det2([3.0, 1.5], [2.0, 4.0]) - 9.0) < 1e-12, \"determinant\"\n    assert abs(det2([1.0, 2.0], [2.0, 4.0])) < 1e-12, \"collinear basis is singular\"\n    checks += 1\n\n    c1, c2 = coordinates_in_basis([5.0, 3.0], [2.0, 0.0], [1.0, 1.0])\n    assert abs(c1 - 1.0) < 1e-12 and abs(c2 - 3.0) < 1e-12, \"coordinates in a basis\"\n    rebuilt = in_basis([4.0, 2.5], [1.2, -0.4], [0.3, 1.7])\n    for got, want in zip(rebuilt, [4.0, 2.5]):\n        assert abs(got - want) < 1e-12, \"round trip\"\n    checks += 1\n\n    refused = False\n    try:\n        coordinates_in_basis([1.0, 1.0], [1.0, 2.0], [2.0, 4.0])\n    except ValueError:\n        refused = True\n    assert refused, \"a singular basis must raise ValueError, not return inf\"\n    checks += 1\n\n    q = plant.ik(0.08, 0.05)\n    x, y = plant.fk(*q)\n    arm_tau = moment([x, y, 0.0], [0.0, -0.20 * plant.G, 0.0])\n    assert abs(arm_tau[2] + 0.20 * plant.G * x) < 1e-12, \"payload moment about the shoulder\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - projection, moment, determinant, basis, refusal, arm payload\"\n          % checks)\n\n\n_selfcheck()\n",
