    "starterCode": "\"\"\"Exercise 00-foundations.T2.00c - the learner's file.\n\nOne first-order response, one second-order response, and the step size where the simulation stops\ntelling the truth. Fill the six TODOs, then run the tests:\n\n    EXERCISE_TARGET=exercises/00-foundations.T2.00c/starter.py \\\n        python3 -m unittest discover -s exercises/00-foundations.T2.00c -p 'test_*.py'\n\nUnits are the module's: seconds, radians, kg*m^2, N*m/rad, N*m*s/rad.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef first_order_response(t, tau):\n    \"\"\"Unit-step response 1 - exp(-t/tau). At t = tau this is 0.6321, by definition.\"\"\"\n    raise NotImplementedError(\"TODO 1: the exponential step response\")\n\n\ndef second_order_params(j, k, b):\n    \"\"\"{\"wn\", \"zeta\", \"wd\", \"mp\"} for J theta'' + b theta' + k theta = k u.\n\n    TODO 2: wn = sqrt(k/J); zeta = b / (2 sqrt(J k)); wd = wn sqrt(1 - zeta^2);\n    mp = exp(-pi zeta / sqrt(1 - zeta^2)). At zeta >= 1 there is no overshoot: mp = 0, wd = 0.\n    \"\"\"\n    raise NotImplementedError(\"TODO 2: the four numbers that describe a second-order system\")\n\n\ndef critical_damping(j, k):\n    \"\"\"The b that makes zeta exactly 1.0.\"\"\"\n    raise NotImplementedError(\"TODO 3: zeta = 1, not b = 2 J k\")\n\n\ndef settling_time(wn, zeta, tolerance=0.02):\n    \"\"\"The 2% settling time, 4 / (zeta * wn) - and refuse zeta <= 0 (it never settles).\"\"\"\n    raise NotImplementedError(\"TODO 4: the envelope decays as exp(-zeta wn t)\")\n\n\ndef simulate_step(j, k, b, dt, steps, theta0=0.0, omega0=0.0):\n    \"\"\"Semi-implicit Euler on J theta'' = k (1 - theta) - b theta'.\n\n    Returns {\"theta\", \"max_theta\", \"mp\"} where mp = max(0, max_theta - 1). Update velocity first,\n    then position with the NEW velocity - the same order the plant uses.\n    \"\"\"\n    raise NotImplementedError(\"TODO 5: the simulation the worked example runs\")\n\n\ndef max_stable_dt(j, k):\n    \"\"\"The largest dt this semi-implicit scheme tolerates for an undamped joint: 2 / wn.\"\"\"\n    raise NotImplementedError(\"TODO 6: the stability limit, not a guess\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 00-foundations.T2.00c.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(first_order_response(0.010, 0.010) - (1.0 - math.exp(-1))) < 1e-12, \"63.2% at tau\"\n    assert first_order_response(0.0, 0.02) == 0.0, \"starts at zero\"\n    checks += 1\n\n    p = second_order_params(0.02, 8.0, 0.40)\n    assert abs(p[\"wn\"] - 20.0) < 1e-9, \"wn\"\n    assert abs(p[\"zeta\"] - 0.50) < 1e-9, \"zeta\"\n    assert abs(p[\"wd\"] - 20.0 * math.sqrt(0.75)) < 1e-9, \"wd\"\n    assert abs(p[\"mp\"] - 0.16303) < 1e-5, \"overshoot\"\n    checks += 1\n\n    assert abs(critical_damping(0.02, 8.0) - 0.80) < 1e-12, \"b_crit = 2 sqrt(J k)\"\n    assert second_order_params(0.02, 8.0, 0.80)[\"zeta\"] == 1.0 or \\\n        abs(second_order_params(0.02, 8.0, 0.80)[\"zeta\"] - 1.0) < 1e-12, \"critical is zeta = 1\"\n    checks += 1\n\n    assert abs(settling_time(20.0, 0.7) - 4.0 / 14.0) < 1e-12, \"2% settling time\"\n    refused = False\n    try:\n        settling_time(20.0, 0.0)\n    except ValueError:\n        refused = True\n    assert refused, \"an undamped system never settles - refuse it\"\n    checks += 1\n\n    sim = simulate_step(0.02, 8.0, 0.40, 1e-4, 10000)\n    assert abs(sim[\"mp\"] - p[\"mp\"]) < 0.001, \"simulated overshoot matches the formula\"\n    assert abs(simulate_step(0.02, 8.0, 0.80, 1e-4, 20000)[\"mp\"]) < 1e-6, \"critical damping\"\n    checks += 1\n\n    limit = max_stable_dt(0.02, 8.0)\n    assert abs(limit - 0.1) < 1e-12, \"2 / wn\"\n    assert abs(simulate_step(0.02, 8.0, 0.0, 0.9 * limit, 4000)[\"max_theta\"]) < 10.0, \"stable below the limit\"\n    assert abs(simulate_step(0.02, 8.0, 0.0, 1.5 * limit, 4000)[\"max_theta\"]) > 100.0, \"unstable above it\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - first order, wn/zeta, critical damping, settling, \"\n          \"simulation, stability limit\" % checks)\n\n\n_selfcheck()\n",
