    "fullSolution": "\"\"\"Exercise 01-electronics.T1.01a - reference solution.\n\nOhm's law, the loaded and unloaded divider, Joule heating, the LED's series resistor, the LED's\nactual current once a resistor is chosen, and the derating rule that keeps a quarter-watt part from\nturning brown.\n\"\"\"\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef stall_current(v_supply, r_winding):\n    \"\"\"I = V / R for a stalled winding.\"\"\"\n    if r_winding <= 0.0:\n        raise ValueError(\"a winding needs a positive resistance\")\n    return v_supply / r_winding\n\n\ndef divider_unloaded(v_in, r1, r2):\n    \"\"\"The midpoint of an unloaded divider; the BOTTOM leg sets the fraction.\"\"\"\n    if r1 <= 0.0 or r2 <= 0.0:\n        raise ValueError(\"both legs need a positive resistance\")\n    return v_in * r2 / (r1 + r2)\n\n\ndef divider_loaded(v_in, r1, r2, r_load):\n    \"\"\"The midpoint with a load in parallel with the bottom leg - always at or below the unloaded.\"\"\"\n    if r_load <= 0.0:\n        raise ValueError(\"a load needs a positive resistance\")\n    bottom = (r2 * r_load) / (r2 + r_load)\n    return divider_unloaded(v_in, r1, bottom)\n\n\ndef joule_power(current, resistance):\n    \"\"\"P = I^2 R.\"\"\"\n    if resistance < 0.0:\n        raise ValueError(\"a resistance cannot be negative\")\n    return current * current * resistance\n\n\ndef led_series_resistor(v_supply, v_led, i_target):\n    \"\"\"KVL first: R = (V_supply - V_LED) / I.\"\"\"\n    if i_target <= 0.0:\n        raise ValueError(\"an LED needs a positive target current\")\n    if v_led > v_supply:\n        raise ValueError(\"the LED's forward voltage exceeds the supply - it will not light\")\n    return (v_supply - v_led) / i_target\n\n\ndef led_current(v_supply, v_led, resistance):\n    \"\"\"The current an already-chosen resistor allows: (V_supply - V_LED) / R.\"\"\"\n    if resistance <= 0.0:\n        raise ValueError(\"the series resistance must be positive\")\n    return max(0.0, (v_supply - v_led) / resistance)\n\n\ndef within_derating(p_dissipated, p_rated, derating=0.5):\n    \"\"\"True when the part runs at or below `derating` of its rating (half by default).\"\"\"\n    if p_rated <= 0.0:\n        raise ValueError(\"a resistor needs a positive rating\")\n    if not 0.0 < derating <= 1.0:\n        raise ValueError(\"the derating fraction is in (0, 1]\")\n    return p_dissipated <= derating * p_rated\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 01-electronics.T1.01a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(stall_current(12.0, 3.0) - 4.0) < 1e-12, \"Ohm's law at stall\"\n    assert abs(stall_current(12.0, 2.4) - 5.0) < 1e-12\n    checks += 1\n\n    unloaded = divider_unloaded(24.0, 68_000.0, 10_000.0)\n    loaded = divider_loaded(24.0, 68_000.0, 10_000.0, 100_000.0)\n    assert abs(unloaded - 3.076923) < 1e-6 and unloaded < 3.3, \"the sensing divider\"\n    assert abs(loaded - 2.830189) < 1e-6 and loaded < unloaded, \"the ADC loads the bottom leg\"\n    assert divider_unloaded(24.0, 10_000.0, 68_000.0) > 20.0, \"the swapped legs destroy the pin\"\n    checks += 1\n\n    assert abs(joule_power(5.0, 2.4) - 60.0) < 1e-12, \"P = I^2 R on a stalled winding\"\n    assert abs(joule_power(10.0, 0.050) - 5.0) < 1e-12\n    checks += 1\n\n    r = led_series_resistor(5.0, 2.1, 0.010)\n    assert abs(r - 290.0) < 1e-9, \"KVL first, then divide\"\n    assert abs(led_current(5.0, 2.1, r) - 0.010) < 1e-12\n    assert abs(joule_power(0.010, r) - 0.029) < 1e-9, \"and the resistor's own heat\"\n    checks += 1\n\n    assert within_derating(0.125, 0.25) and not within_derating(0.2, 0.25), \"half the rating\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - Ohm's law, the loaded divider, Joule heating, the LED's \"\n          \"series resistor and the half-rating rule\" % checks)\n\n\n_selfcheck()\n",
