    "fullSolution": "\"\"\"Exercise 01-electronics.T1.01b - reference solution.\n\nA low-side MOSFET's conduction loss, a PWM duty cycle's average voltage, the shoot-through current\nof a leg with no dead time, an H-bridge's differential drive, the two-switch conduction path, the\ndatasheet's recommended window and the duty that produces a wanted average.\n\"\"\"\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef conduction_loss(current, rds_on, duty=1.0):\n    \"\"\"P = I^2 R_DS(on) D over one PWM period.\"\"\"\n    if rds_on < 0.0:\n        raise ValueError(\"an on-resistance cannot be negative\")\n    if not 0.0 <= duty <= 1.0:\n        raise ValueError(\"duty is a fraction in [0, 1]\")\n    return current * current * rds_on * duty\n\n\ndef pwm_effective_voltage(v_bus, duty):\n    \"\"\"V_eff = D * V_bus.\"\"\"\n    if not 0.0 <= duty <= 1.0:\n        raise ValueError(\"duty is a fraction in [0, 1], not a percentage\")\n    return duty * v_bus\n\n\ndef shoot_through_current(v_bus, rds_on):\n    \"\"\"The leg's short-circuit current when both switches are on: V_bus / (2 R_DS(on)).\"\"\"\n    if rds_on <= 0.0:\n        raise ValueError(\"an on-resistance must be positive\")\n    return v_bus / (2.0 * rds_on)\n\n\ndef h_bridge_voltage(v_bus, duty_a, duty_b):\n    \"\"\"The average signed terminal voltage: (D_A - D_B) V_bus.\"\"\"\n    for duty in (duty_a, duty_b):\n        if not 0.0 <= duty <= 1.0:\n            raise ValueError(\"each leg's duty is a fraction in [0, 1]\")\n    return (duty_a - duty_b) * v_bus\n\n\ndef bridge_conduction_loss(current, r_high, r_low, duty=1.0):\n    \"\"\"Motor current crosses TWO switches: P = I^2 (R_high + R_low) D.\"\"\"\n    if r_high < 0.0 or r_low < 0.0:\n        raise ValueError(\"on-resistances cannot be negative\")\n    if not 0.0 <= duty <= 1.0:\n        raise ValueError(\"duty is a fraction in [0, 1]\")\n    return current * current * (r_high + r_low) * duty\n\n\ndef within_recommended(v_supply, v_min=2.7, v_max=10.8):\n    \"\"\"True inside the datasheet's Recommended Operating Conditions.\"\"\"\n    if v_min <= 0.0 or v_max <= v_min:\n        raise ValueError(\"the recommended window is a positive, increasing interval\")\n    return v_min <= v_supply <= v_max\n\n\ndef duty_for_effective_voltage(v_eff, v_bus):\n    \"\"\"D = V_eff / V_bus, refusing a demand the bus cannot deliver.\"\"\"\n    if v_bus <= 0.0:\n        raise ValueError(\"the bus voltage must be positive\")\n    duty = v_eff / v_bus\n    if not 0.0 <= duty <= 1.0:\n        raise ValueError(\"that average voltage is outside what this bus can produce\")\n    return duty\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 01-electronics.T1.01b.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(conduction_loss(5.0, 0.010) - 0.25) < 1e-12, \"I^2 R on-resistance loss\"\n    assert abs(conduction_loss(4.0, 0.020, 0.5) - 0.16) < 1e-12, \"and the duty scales the average\"\n    checks += 1\n\n    assert abs(pwm_effective_voltage(12.0, 0.75) - 9.0) < 1e-12\n    assert abs(pwm_effective_voltage(12.0, 0.65) - 7.8) < 1e-12\n    try:\n        pwm_effective_voltage(12.0, 65.0)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError(\"a percentage is not a duty fraction\")\n    checks += 1\n\n    assert abs(shoot_through_current(12.0, 0.020) - 300.0) < 1e-9, \"two switches in series\"\n    assert abs(shoot_through_current(24.0, 0.010) - 1200.0) < 1e-9\n    checks += 1\n\n    assert abs(h_bridge_voltage(12.0, 1.0, 0.0) - 12.0) < 1e-12, \"forward\"\n    assert abs(h_bridge_voltage(24.0, 0.25, 0.75) + 12.0) < 1e-9, \"reverse at half the bus\"\n    assert abs(bridge_conduction_loss(1.2, 0.18, 0.18) - 0.5184) < 1e-4, \"two switches in the loop\"\n    checks += 1\n\n    assert within_recommended(9.0) and within_recommended(10.8), \"the recommended window\"\n    assert not within_recommended(11.8), \"the absolute maximum is not an operating point\"\n    assert abs(duty_for_effective_voltage(9.0, 12.0) - 0.75) < 1e-12, \"the duty round trip\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - conduction loss, the PWM average, the shoot-through current, \"\n          \"the H-bridge's differential drive and the datasheet window\" % checks)\n\n\n_selfcheck()\n",
    "expectedOutput": "SELF-CHECK PASS: 5 checks - conduction loss, the PWM average, the shoot-through current, the H-bridge's differential drive and the datasheet window",
