    "fullSolution": "\"\"\"Exercise 01-electronics.T1.01d - reference solution.\n\nThe RC time constant and the charging curve, the -3 dB corner it defines, the bulk capacitance a\ndroop budget demands, the energy stored in a capacitor and in a coil, and the flyback spike an\nunprotected coil produces when its current is interrupted.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef rc_time_constant(r_ohm, c_farad):\n    \"\"\"tau = R C, in seconds.\"\"\"\n    if r_ohm <= 0.0 or c_farad <= 0.0:\n        raise ValueError(\"a time constant needs a positive resistance and capacitance\")\n    return r_ohm * c_farad\n\n\ndef rc_voltage(t_s, v_in, r_ohm, c_farad):\n    \"\"\"V_C(t) = V_in (1 - exp(-t / RC)) for a capacitor charging from zero.\"\"\"\n    if t_s < 0.0:\n        raise ValueError(\"time does not run backwards\")\n    return v_in * (1.0 - math.exp(-t_s / rc_time_constant(r_ohm, c_farad)))\n\n\ndef rc_cutoff_hz(r_ohm, c_farad):\n    \"\"\"fc = 1 / (2 pi R C): the -3 dB half-power corner.\"\"\"\n    return 1.0 / (2.0 * math.pi * rc_time_constant(r_ohm, c_farad))\n\n\ndef bulk_capacitance_f(delta_i, delta_t, delta_v):\n    \"\"\"C >= delta_I * delta_t / delta_V for a droop budget.\"\"\"\n    if delta_v <= 0.0:\n        raise ValueError(\"a droop budget must be positive\")\n    if delta_t < 0.0:\n        raise ValueError(\"the transient duration cannot be negative\")\n    return delta_i * delta_t / delta_v\n\n\ndef capacitor_energy(v_cap, c_farad):\n    \"\"\"E_C = 1/2 C V^2, in joules.\"\"\"\n    if c_farad < 0.0:\n        raise ValueError(\"a capacitance cannot be negative\")\n    return 0.5 * c_farad * v_cap * v_cap\n\n\ndef inductor_energy(inductance_h, current):\n    \"\"\"E_L = 1/2 L I^2, in joules.\"\"\"\n    if inductance_h < 0.0:\n        raise ValueError(\"an inductance cannot be negative\")\n    return 0.5 * inductance_h * current * current\n\n\ndef flyback_voltage(inductance_h, current, dt_open_s):\n    \"\"\"The unclamped spike |V_L| = L dI/dt when a coil's current is interrupted in dt_open_s.\"\"\"\n    if dt_open_s <= 0.0:\n        raise ValueError(\"interrupting a current takes a positive time\")\n    if inductance_h < 0.0:\n        raise ValueError(\"an inductance cannot be negative\")\n    return inductance_h * current / dt_open_s\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 01-electronics.T1.01d.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(rc_time_constant(10_000.0, 0.1e-6) - 1e-3) < 1e-15, \"tau = RC\"\n    assert abs(rc_time_constant(4700.0, 10e-6) - 0.047) < 1e-15\n    assert abs(rc_cutoff_hz(10_000.0, 0.1e-6) - 159.154943) < 1e-5, \"and the corner it sets\"\n    checks += 1\n\n    assert abs(rc_voltage(1e-3, 3.3, 10_000.0, 0.1e-6) - 2.085998) < 1e-6, \"63% at one tau\"\n    assert abs(rc_voltage(5e-3, 3.3, 10_000.0, 0.1e-6) - 3.277765) < 1e-6, \"99.3% at five\"\n    checks += 1\n\n    assert abs(bulk_capacitance_f(3.0, 20e-6, 0.25) - 2.4e-4) < 1e-15, \"the 240 uF budget\"\n    assert abs(bulk_capacitance_f(3.0, 20e-6, 0.6) - 1.0e-4) < 1e-15, \"a 100 uF part sags 0.6 V\"\n    try:\n        bulk_capacitance_f(3.0, 20e-6, 0.0)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError(\"a droop budget must be positive\")\n    checks += 1\n\n    assert abs(capacitor_energy(12.0, 100e-6) - 0.0072) < 1e-15, \"1/2 C V^2\"\n    assert abs(inductor_energy(0.003, 2.0) - 0.006) < 1e-15, \"1/2 L I^2\"\n    checks += 1\n\n    spike = flyback_voltage(0.003, 2.0, 0.5e-6)\n    assert abs(spike - 12_000.0) < 1e-6, \"the unclamped kick\"\n    assert spike > 500.0 * (12.0 + 0.7), \"and the diode clamps it to the bus\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the RC time constant and corner, the charging curve, the \"\n          \"droop budget, both stored energies and the flyback spike\" % checks)\n\n\n_selfcheck()\n",
