    "starterCode": "\"\"\"Exercise 01-electronics.T3.01a - the learner's file.\n\nThe commutation-loop inductance and its turn-off spike, mutual-inductance flux cancellation, the\nBessel group delay and Q, and the SAR charge bucket and Cauer thermal ladder. Fill the eight TODOs:\n\n    EXERCISE_TARGET=exercises/01-electronics.T3.01a/starter.py \\\n        python3 -m unittest discover -s exercises/01-electronics.T3.01a -p 'test_*.py'\n\"\"\"\n\nimport math\n\nMU0 = 4.0 * math.pi * 1e-7  # H/m\n\n\ndef loop_inductance_nh(h_m, w_m, length_m, mu0=MU0):\n    \"\"\"L_loop = mu0 (h / w) length, in nanohenries.\"\"\"\n    raise NotImplementedError(\"TODO 1: height OVER width, then the length, then 1e9 for nH\")\n\n\ndef flux_cancelled_nh(l1_nh, l2_nh, m_nh):\n    \"\"\"L_loop = L1 + L2 - 2 M, in nH.\"\"\"\n    raise NotImplementedError(\"TODO 2: the mutual term is counted TWICE and SUBTRACTED\")\n\n\ndef turn_off_peak_v(v_bus, l_loop_nh, di_dt_a_per_ns):\n    \"\"\"V_DS,peak = V_bus + L_loop di/dt.\"\"\"\n    raise NotImplementedError(\"TODO 3: nH times A/ns is already volts - no 1e-9 or 1e9 here\")\n\n\ndef bessel_group_delay_us(f0_hz):\n    \"\"\"tau_g0 = 1 / (2 pi f0), in microseconds.\"\"\"\n    raise NotImplementedError(\"TODO 4: the 2 pi and the micro prefix are both easy to drop\")\n\n\ndef bessel_q():\n    \"\"\"The Q of a 2nd-order Bessel filter.\"\"\"\n    raise NotImplementedError(\"TODO 5: 1 / sqrt(3), about 0.577 - not 1/sqrt(2)\")\n\n\ndef charge_droop_fraction(c_sample_f, c_filt_f):\n    \"\"\"The t = 0+ droop fraction of a SAR charge bucket.\"\"\"\n    raise NotImplementedError(\"TODO 6: the bucket and the sampling capacitor SHARE the step\")\n\n\ndef charge_settling_lsb(bits, c_sample_f, c_filt_f, r_filt_ohm, t_acq_s):\n    \"\"\"Residual settling error in LSBs after t_acq.\"\"\"\n    raise NotImplementedError(\n        \"TODO 7: 2**bits times the droop, decayed by exp(-t / (R_filt C_filt)) - C_filt, not the sum\"\n    )\n\n\ndef cauer_junction_c(t_amb_c, p_loss_w, stages, t_s):\n    \"\"\"Junction temperature of a Cauer ladder under a rectangular pulse.\"\"\"\n    raise NotImplementedError(\"TODO 8: each stage is R (1 - exp(-t / tau)); add the rises\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 01-electronics.T3.01a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    six = loop_inductance_nh(0.00010, 0.012, 0.015)\n    two = loop_inductance_nh(0.00160, 0.0020, 0.025)\n    assert abs(six - 0.157079633) < 1e-9, \"0.10 mm prepreg over a 12 mm plane\"\n    assert abs(two - 25.132741229) < 1e-6, \"1.60 mm core over a 2 mm trace\"\n    assert abs(two / six - 160.0) < 1e-9, \"the stackup, not the copper, sets the ratio\"\n    assert abs(turn_off_peak_v(48.0, six, 3.0) - 48.471238898) < 1e-9\n    assert turn_off_peak_v(48.0, two, 3.0) > 120.0, \"a 2-layer loop avalanches an 80 V FET\"\n    assert abs(flux_cancelled_nh(6.0, 6.0, 5.2) - 1.6) < 1e-12, \"6 + 6 - 2(5.2)\"\n    checks += 1\n\n    assert abs(bessel_group_delay_us(250_000.0) - 0.636619772) < 1e-9, \"1 / (2 pi f0)\"\n    assert abs(bessel_group_delay_us(200_000.0) - 0.795774715) < 1e-9\n    assert abs(bessel_q() - 1.0 / math.sqrt(3.0)) < 1e-12, \"Q = 0.5774, not 0.7071\"\n    checks += 1\n\n    assert abs(charge_droop_fraction(6e-12, 114e-12) - 0.05) < 1e-15, \"the capacitors set t = 0+\"\n    late = charge_settling_lsb(12, 6e-12, 114e-12, 50.0, 34.2e-9)\n    assert abs(late - 0.507648446) < 1e-9, \"0.5076 LSB at 34.2 ns - just over budget\"\n    assert charge_settling_lsb(12, 6e-12, 114e-12, 50.0, 35e-9) < 0.5\n    broken = charge_settling_lsb(12, 6e-12, 114e-12, 10_000.0, 34.2e-9)\n    assert abs(broken / late - 391.51) < 0.05, \"a leftover 10 kOhm series resistor\"\n    checks += 1\n\n    stages = [(0.45, 0.005), (2.5, 30.0)]\n    junction = cauer_junction_c(25.0, 120.0, stages, 0.010)\n    assert abs(junction - 71.791878) < 1e-6, \"die +46.7 C, sink +0.1 C\"\n    assert junction < 125.0\n    assert abs(cauer_junction_c(30.0, 20.0, [(0.5, 10.0), (0.2, 100.0), (2.3, 1000.0)], 1e5)\n               - 90.0) < 1e-9, \"steady state is the sum of the R_thetas\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the flux-cancelling loop inductance and its turn-off spike, \"\n          \"the Bessel group delay and Q, the SAR charge bucket's droop and settling, and the Cauer \"\n          \"junction temperature\" % checks)\n\n\n_selfcheck()\n",
