    "starterCode": "\"\"\"Exercise 02-mechanics.T1.02a - the learner's file.\n\nThe lever-arm gravity torque, a balancing force from static equilibrium, the gear ratio and its\nspeed, torque and power, and the reflected inertia. Fill the seven TODOs:\n\n    EXERCISE_TARGET=exercises/02-mechanics.T1.02a/starter.py \\\n        python3 -m unittest discover -s exercises/02-mechanics.T1.02a -p 'test_*.py'\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant\n\n\ndef gravity_torque(theta_rad, m_link, l_com, m_tip=0.0, l_total=0.0, g=9.81):\n    \"\"\"tau_g = (m_link l_com + m_tip l_total) g cos(theta).\"\"\"\n    raise NotImplementedError(\"TODO 1: COSINE, because theta is measured from horizontal\")\n\n\ndef balance_force(force_1, x_1, x_2):\n    \"\"\"The upward force at x_2 that balances F_1 at x_1.\"\"\"\n    raise NotImplementedError(\"TODO 2: a longer lever needs less force, so divide by x_2\")\n\n\ndef gear_ratio(z_driven, z_driver):\n    \"\"\"N = driven teeth / driver teeth.\"\"\"\n    raise NotImplementedError(\"TODO 3: the DRIVEN pulley is on top of the fraction\")\n\n\ndef gear_output_speed(omega_motor, ratio):\n    \"\"\"A reducer slows the output.\"\"\"\n    raise NotImplementedError(\"TODO 4: a reducer divides the speed by N\")\n\n\ndef gear_output_torque(tau_motor, ratio, eta=1.0):\n    \"\"\"A reducer multiplies torque.\"\"\"\n    raise NotImplementedError(\"TODO 5: eta * N * tau_motor - the efficiency is part of it\")\n\n\ndef mechanical_power(torque, omega):\n    \"\"\"P = tau * omega.\"\"\"\n    raise NotImplementedError(\"TODO 6: multiply\")\n\n\ndef reflected_inertia(j_motor, ratio):\n    \"\"\"Inertia seen at the output.\"\"\"\n    raise NotImplementedError(\"TODO 7: the ratio is SQUARED\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 02-mechanics.T1.02a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(gravity_torque(0.0, 0.40, 0.10, 0.50, 0.20) - 1.3734) < 1e-9, \"horizontal lever\"\n    assert abs(gravity_torque(math.pi / 3.0, 0.40, 0.10, 0.50, 0.20) - 0.6867) < 1e-9\n    assert abs(gravity_torque(math.pi / 2.0, 1.0, 0.30)) < 1e-9, \"overhead has no lever arm\"\n    assert gravity_torque(0.0, 0.8, 0.25) > gravity_torque(math.pi / 4.0, 0.8, 0.25)\n    checks += 1\n\n    assert abs(balance_force(30.0, 0.20, 0.10) - 60.0) < 1e-12, \"static equilibrium\"\n    assert abs(balance_force(30.0, 0.20, 0.40) - 15.0) < 1e-12\n    checks += 1\n\n    assert abs(gear_ratio(72, 16) - 4.5) < 1e-12, \"driven over driver\"\n    assert abs(gear_output_speed(90.0, 4.5) - 20.0) < 1e-12, \"a reducer slows the output\"\n    assert abs(gear_output_torque(0.40, 4.5, 0.95) - 1.71) < 1e-12, \"and multiplies the torque\"\n    checks += 1\n\n    out_torque = gear_output_torque(0.40, 4.5, 0.95)\n    out_speed = gear_output_speed(90.0, 4.5)\n    assert abs(mechanical_power(out_torque, out_speed) - 0.95 * mechanical_power(0.40, 90.0)) < 1e-9\n    assert abs(reflected_inertia(1e-5, 4.5) - 2.025e-4) < 1e-15, \"the ratio is squared\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the lever-arm gravity torque, the balancing force, the gear \"\n          \"ratio with its speed and torque, power conservation and reflected inertia\" % checks)\n\n\n_selfcheck()\n",
