    "starterCode": "\"\"\"Exercise 03-sensors.T1.03a - the learner's file.\n\nTorque from current, back-EMF from speed, pole pairs from magnets, the electrical angle, the\nquadrature count and its resolution, and one Gray-code step. Fill the eight TODOs:\n\n    EXERCISE_TARGET=exercises/03-sensors.T1.03a/starter.py \\\n        python3 -m unittest discover -s exercises/03-sensors.T1.03a -p 'test_*.py'\n\"\"\"\n\nimport math\n\nTAU = 2.0 * math.pi\n\n\ndef back_emf(ke_v_s_rad, omega_m_rad_s):\n    \"\"\"v_bemf = Ke * omega_m in volts.\"\"\"\n    raise NotImplementedError(\"TODO 1: the EMF is the constant TIMES the speed\")\n\n\ndef winding_current(v_term_v, omega_m_rad_s, ke_v_s_rad, r_ohm):\n    \"\"\"i = (V_term - Ke omega_m) / R in amperes.\"\"\"\n    raise NotImplementedError(\"TODO 2: subtract the back-EMF before dividing by R\")\n\n\ndef motor_torque(kt_nm_a, current_a):\n    \"\"\"tau = Kt * i in N*m.\"\"\"\n    raise NotImplementedError(\"TODO 3: torque is the constant times the current\")\n\n\ndef pole_pairs(n_poles):\n    \"\"\"Number of North-South magnet pairs.\"\"\"\n    raise NotImplementedError(\"TODO 4: 14P is 14 MAGNETS, so p = 14 / 2 = 7\")\n\n\ndef electrical_angle(theta_m_rad, p):\n    \"\"\"theta_e = (p * theta_m) mod 2*pi, wrapped into [0, 2*pi).\"\"\"\n    raise NotImplementedError(\"TODO 5: multiply by p, then wrap into one electrical cycle\")\n\n\ndef quadrature_cpr(n_lines):\n    \"\"\"Counts per mechanical revolution, 4x decoded.\"\"\"\n    raise NotImplementedError(\"TODO 6: four edges per line, not one\")\n\n\ndef angle_resolution(counts_per_rev):\n    \"\"\"(radians, degrees) per count.\"\"\"\n    raise NotImplementedError(\"TODO 7: 2*pi / CPR radians, 360 / CPR degrees\")\n\n\ndef quad_step(prev_ab, curr_ab):\n    \"\"\"+1 forward, -1 reverse, 0 for no change or an invalid two-bit jump.\"\"\"\n    raise NotImplementedError(\"TODO 8: only ONE bit may change in a valid step\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 03-sensors.T1.03a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, constant time,\none PASS line.\n\"\"\"\n\nimport math\n\nTAU = 2.0 * math.pi\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert abs(back_emf(0.05, 100.0) - 5.0) < 1e-12, \"Ke times omega\"\n    assert abs(winding_current(12.0, 100.0, 0.05, 2.0) - 3.5) < 1e-12, \"the EMF is subtracted\"\n    assert abs(winding_current(12.0, 200.0, 0.06, 4.0)) < 1e-12, \"no-load draws nothing\"\n    assert abs(motor_torque(0.05, 3.5) - 0.175) < 1e-12, \"Kt times i\"\n    checks += 1\n\n    assert pole_pairs(14) == 7, \"14 magnets are 7 pole pairs\"\n    assert pole_pairs(28) == 14\n    assert abs(electrical_angle(math.pi / 7.0, 7) - math.pi) < 1e-12, \"one cycle per seventh\"\n    assert abs(electrical_angle(1.0, 7) - 0.7168146928204138) < 1e-12, \"wrapped into one cycle\"\n    checks += 1\n\n    assert quadrature_cpr(1024) == 4096, \"four edges per line\"\n    assert quadrature_cpr(500) == 2000\n    radians, degrees = angle_resolution(4096)\n    assert abs(degrees - 0.087890625) < 1e-12, \"360 over CPR\"\n    assert abs(radians - TAU / 4096.0) < 1e-18\n    checks += 1\n\n    forward = [0b00, 0b10, 0b11, 0b01, 0b00, 0b10]\n    assert sum(quad_step(a, b) for a, b in zip(forward, forward[1:])) == 5, \"Gray-code forward\"\n    backward = list(reversed(forward))\n    assert sum(quad_step(a, b) for a, b in zip(backward, backward[1:])) == -5\n    assert quad_step(0b00, 0b11) == 0, \"two bits at once is not a step\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - back-EMF and the current it leaves, pole pairs and the \"\n          \"wrapped electrical angle, 4x quadrature counts with their resolution, and the Gray-code \"\n          \"step that refuses a two-bit jump\" % checks)\n\n\n_selfcheck()\n",
