    "fullSolution": "\"\"\"Exercise 03-sensors.T2.03a - reference solution.\n\nThree frames and one tracking loop. The Clarke transform is amplitude-invariant, the Park transform\nis a rotation whose determinant is one, and the PLL's residual must be wrapped before it is used:\nan encoder that rolls over from 2*pi to 0 otherwise hands the loop a step it reads as a real\n2*pi error, and the velocity estimate spikes exactly once per turn.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef wrap_pi(angle):\n    \"\"\"Wrap an angle into (-pi, pi].\"\"\"\n    wrapped = math.fmod(angle + math.pi, 2.0 * math.pi)\n    if wrapped <= 0.0:\n        wrapped += 2.0 * math.pi\n    return wrapped - math.pi\n\n\ndef third_phase(i_a, i_b):\n    \"\"\"The neutral star point forces `i_c = -(i_a + i_b)`.\"\"\"\n    return -(i_a + i_b)\n\n\ndef clarke(i_a, i_b):\n    \"\"\"Amplitude-invariant Clarke: (i_alpha, i_beta) from two phase currents.\"\"\"\n    return i_a, (i_a + 2.0 * i_b) / math.sqrt(3.0)\n\n\ndef park(i_alpha, i_beta, theta_e):\n    \"\"\"Rotate the stationary frame onto the rotor: the inverse of the rotor's own rotation.\"\"\"\n    c = math.cos(theta_e)\n    s = math.sin(theta_e)\n    return c * i_alpha + s * i_beta, -s * i_alpha + c * i_beta\n\n\ndef inverse_park(i_d, i_q, theta_e):\n    \"\"\"(i_alpha, i_beta) from the rotor frame - Park's transpose, since it is a rotation.\"\"\"\n    c = math.cos(theta_e)\n    s = math.sin(theta_e)\n    return c * i_d - s * i_q, s * i_d + c * i_q\n\n\ndef pll_step(theta_hat, omega_hat, theta_meas, kp, ki, dt):\n    \"\"\"One Type-II tracking-loop step; returns (theta_hat, omega_hat) after `dt`.\n\n    The residual is wrapped: the measurement and the estimate live on a circle, and their plain\n    difference jumps by 2*pi at the rollover.\n    \"\"\"\n    error = wrap_pi(theta_meas - theta_hat)\n    omega_hat = omega_hat + ki * error * dt\n    theta_hat = wrap_pi(theta_hat + (omega_hat + kp * error) * dt)\n    return theta_hat, omega_hat\n\n\ndef allan_deviation(sigma_density, tau):\n    \"\"\"Rate standard deviation after averaging white noise of density `sigma_density` for `tau`.\"\"\"\n    if tau <= 0.0:\n        raise ValueError(\"averaging window must be positive\")\n    return sigma_density / math.sqrt(tau)\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 03-sensors.T2.03a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    ia, ib = 6.0, -2.0\n    assert abs(third_phase(ia, ib) + 4.0) < 1e-15, \"the neutral point gives i_c\"\n    alpha, beta = clarke(ia, ib)\n    assert abs(alpha - 6.0) < 1e-12 and abs(beta - 2.0 / math.sqrt(3.0)) < 1e-12, \"Clarke\"\n    assert abs(math.hypot(alpha, beta) - 6.110101) < 1e-5, \"vector magnitude\"\n    checks += 1\n\n    i_d, i_q = park(5.0, 0.0, math.pi / 2.0)\n    assert abs(i_d) < 1e-12 and abs(i_q + 5.0) < 1e-12, \"a quarter turn about the rotor\"\n    checks += 1\n\n    theta = 0.85\n    ia = -10.0 * math.sin(theta)\n    ib = -10.0 * math.sin(theta - 2.0 * math.pi / 3.0)\n    alpha, beta = clarke(ia, ib)\n    i_d, i_q = park(alpha, beta, theta)\n    assert abs(i_d) < 1e-9 and abs(i_q - 10.0) < 1e-9, \"quadrature current demodulates to DC\"\n    checks += 1\n\n    alpha2, beta2 = inverse_park(3.0, -4.0, 1.1)\n    i_d2, i_q2 = park(alpha2, beta2, 1.1)\n    assert abs(i_d2 - 3.0) < 1e-12 and abs(i_q2 + 4.0) < 1e-12, \"Park is a rotation\"\n    checks += 1\n\n    assert abs(wrap_pi(2.0 * math.pi + 0.1) - 0.1) < 1e-12, \"rollover\"\n    assert abs(wrap_pi(-10.0) - (-10.0 + 4.0 * math.pi)) < 1e-9, \"two full turns back\"\n    assert abs(wrap_pi(math.pi) - math.pi) < 1e-12, \"pi is inside (-pi, pi]\"\n    checks += 1\n\n    omega = 100.0\n    zeta, wn = 0.9, 2.0 * math.pi * 30.0\n    kp, ki = 2.0 * zeta * wn, wn * wn\n    dt = 1e-4\n    theta_hat, omega_hat = 0.0, 0.0\n    theta = 0.0\n    for _ in range(3000):\n        theta = wrap_pi(theta + omega * dt)\n        theta_hat, omega_hat = pll_step(theta_hat, omega_hat, theta, kp, ki, dt)\n    assert abs(omega_hat - omega) < 0.01 * omega, \"the loop locks onto the speed\"\n    checks += 1\n\n    tau_hat, omega_hat = pll_step(wrap_pi(2.0 * math.pi - 0.01), 1.0, 0.01, 200.0, 5000.0, 1e-3)\n    assert abs(omega_hat - 1.0) < 0.5, \"a rollover must not spike the velocity\"\n    checks += 1\n\n    assert abs(allan_deviation(0.02, 100.0) - 0.002) < 1e-15, \"tau^-1/2\"\n    assert abs(allan_deviation(0.02, 1.0) / allan_deviation(0.02, 100.0) - 10.0) < 1e-9, \"a decade\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - Clarke and the third phase, Park at a quarter turn, \"\n          \"quadrature demodulation, the inverse, the wrap, the PLL lock and its rollover, \"\n          \"and the averaging law\" % checks)\n\n\n_selfcheck()\n",
