    "fullSolution": "\"\"\"Exercise 04-embedded.T2.04d - reference solution.\n\nFour budgets and one clock. The wire budget is `bits per byte` - 10 on an 8N1 UART, 8 on CAN-FD -\nand the utilisation is the sum of `frequency * wire_time`, which is the number that has to stay\nbelow one. The clock offset is the NTP midpoint, exact only while the two directions are\nsymmetric: an asymmetric link biases it by half the difference.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef wire_time_us(payload_bytes, xrce_bytes, bits_per_byte, bit_rate):\n    \"\"\"Wire time for one message, in microseconds, framing included.\"\"\"\n    if bit_rate <= 0.0:\n        raise ValueError(\"bit rate must be positive\")\n    bits = bits_per_byte * (payload_bytes + xrce_bytes)\n    return 1e6 * bits / bit_rate\n\n\ndef link_utilization(streams, bits_per_byte, bit_rate):\n    \"\"\"Sum over `(frequency_hz, payload_bytes, xrce_bytes)` streams of `f * t_wire`.\"\"\"\n    total = 0.0\n    for frequency, payload, xrce in streams:\n        total += frequency * wire_time_us(payload, xrce, bits_per_byte, bit_rate)\n    return total / 1e6\n\n\ndef handle_total(n_timers, n_subs, n_srvs, n_clients):\n    \"\"\"The exact static capacity `rclc_executor_init` needs.\"\"\"\n    return n_timers + n_subs + n_srvs + n_clients\n\n\ndef spin_wcet_us(t_io_us, callbacks_us):\n    \"\"\"Worst-case time for one `rclc_executor_spin_some`: transport I/O plus every callback.\"\"\"\n    return t_io_us + sum(callbacks_us)\n\n\ndef ntp_rtt_us(t1_mcu, t2_host, t3_host, t4_mcu):\n    \"\"\"Round-trip delay: the four timestamps minus the host's own processing time.\"\"\"\n    return (t4_mcu - t1_mcu) - (t3_host - t2_host)\n\n\ndef ntp_offset_us(t1_mcu, t2_host, t3_host, t4_mcu):\n    \"\"\"Clock offset such that `t_ros2 ~= t_mcu + offset`, from the NTP midpoint.\"\"\"\n    return ((t2_host - t1_mcu) + (t3_host - t4_mcu)) / 2.0\n\n\ndef rtos_utilization(tasks):\n    \"\"\"`sum(C_i / T_i)` over `(execution_us, period_us)` tasks.\"\"\"\n    if any(period <= 0.0 for _, period in tasks):\n        raise ValueError(\"every period must be positive\")\n    return sum(execution / period for execution, period in tasks)\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 04-embedded.T2.04d.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\n\ndef _selfcheck():\n    checks = 0\n\n    wire = wire_time_us(32, 14, 10, 921600.0)\n    assert abs(wire - 499.1319) < 1e-4, \"the 8N1 exercise\"\n    assert abs(wire_time_us(48, 16, 8, 5_000_000.0) - 102.4) < 1e-9, \"CAN-FD, 64 bytes\"\n    assert abs(wire_time_us(24, 16, 8, 5_000_000.0) - 64.0) < 1e-9, \"CAN-FD, 40 bytes\"\n    checks += 1\n\n    link = link_utilization([(500.0, 48, 16), (500.0, 24, 16)], 8, 5_000_000.0)\n    assert abs(link - 0.0832) < 1e-9, \"8.32% of a 5 Mbps bus\"\n    assert link_utilization([(3000.0, 32, 14)], 10, 921600.0) > 1.0, \"a saturated link\"\n    checks += 1\n\n    assert handle_total(1, 2, 1, 0) == 4, \"static handle count\"\n    assert abs(spin_wcet_us(35.0, [45.0, 30.0, 25.0, 50.0]) - 185.0) < 1e-12, \"spin WCET\"\n    assert spin_wcet_us(35.0, [45.0, 30.0, 25.0, 50.0]) < 2000.0, \"inside a 500 Hz thread\"\n    checks += 1\n\n    rtt = ntp_rtt_us(1000.0, 500120.0, 500150.0, 1270.0)\n    offset = ntp_offset_us(1000.0, 500120.0, 500150.0, 1270.0)\n    assert abs(rtt - 240.0) < 1e-9, \"round trip\"\n    assert abs(offset - 499000.0) < 1e-9, \"clock offset\"\n    assert abs(ntp_offset_us(200.0, 10300.0, 10340.0, 440.0) - 10000.0) < 1e-9, \"the module exercise\"\n    checks += 1\n\n    true_offset, delay, process = 1234.5, 60.0, 15.0\n    t1 = 10.0\n    t2 = t1 + delay + true_offset\n    t3 = t2 + process\n    t4 = t3 + delay - true_offset\n    assert abs(ntp_offset_us(t1, t2, t3, t4) - true_offset) < 1e-9, \"symmetric links are exact\"\n    assert abs(ntp_rtt_us(t1, t2, t3, t4) - 2.0 * delay) < 1e-9, \"rtt without host processing\"\n    # True offset 1000 us, forward delay 100 us, reverse delay 170 us: the midpoint reads 965.\n    assert abs(ntp_offset_us(0.0, 1100.0, 1110.0, 280.0) - 965.0) < 1e-9, \"asymmetric bias\"\n    checks += 1\n\n    util = rtos_utilization([(100.0, 500.0), (300.0, 2000.0), (1000.0, 10000.0)])\n    assert abs(util - 0.45) < 1e-12, \"45% of the CPU\"\n    assert rtos_utilization([(600.0, 1000.0), (600.0, 1000.0)]) > 1.0, \"an overloaded set\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - UART and CAN-FD wire time, the utilisation budget, the \"\n          \"handle count, the spin WCET, the NTP offset and round trip, and the RTOS load\" % checks)\n\n\n_selfcheck()\n",
