    "starterCode": "\"\"\"Exercise 04-embedded.T3.04a - the learner's file.\n\nThe center-aligned auto-reload value and the low-side window it leaves open, the Q1.31 word the\nCORDIC coprocessor takes, the even/odd sequence check, and the ISR's share of the CPU. Fill the\neight TODOs:\n\n    EXERCISE_TARGET=exercises/04-embedded.T3.04a/starter.py \\\n        python3 -m unittest discover -s exercises/04-embedded.T3.04a -p 'test_*.py'\n\"\"\"\n\nimport math\n\nQ31_SCALE = 1 << 31\nQ31_MIN = -(1 << 31)\nQ31_MAX = (1 << 31) - 1\n\n\ndef center_aligned_arr(f_tim_hz, f_pwm_hz):\n    \"\"\"ARR = f_tim / (2 f_pwm).\"\"\"\n    raise NotImplementedError(\"TODO 1: up-down mode spends TWO timer ticks per PWM period\")\n\n\ndef pwm_frequency(f_tim_hz, arr):\n    \"\"\"f_pwm = f_tim / (2 ARR).\"\"\"\n    raise NotImplementedError(\"TODO 2: the same factor of two, solved for the frequency\")\n\n\ndef low_side_window_ns(d_max, t_dead_ns, f_pwm_hz):\n    \"\"\"t_low,min = (1 - d_max) T_pwm - 2 t_dead.\"\"\"\n    raise NotImplementedError(\"TODO 3: there is a dead time at BOTH edges, so subtract two\")\n\n\ndef q31_encode(x):\n    \"\"\"X = clamp(round(x * 2^31), -2^31, 2^31 - 1).\"\"\"\n    raise NotImplementedError(\"TODO 4: the scale is 2 to the 31, and +1.0 clamps to 0x7FFFFFFF\")\n\n\ndef q31_decode(word):\n    \"\"\"x_hat = X / 2^31.\"\"\"\n    raise NotImplementedError(\"TODO 5: divide by the same 2^31, not by 2^30\")\n\n\ndef angle_to_q31(theta_rad):\n    \"\"\"x = theta / pi, then encoded.\"\"\"\n    raise NotImplementedError(\"TODO 6: divide by PI first - the format is the normalised angle\")\n\n\ndef seqlock_valid(s1, s2):\n    \"\"\"Tear-free iff s1 is even and s1 == s2.\"\"\"\n    raise NotImplementedError(\"TODO 7: an odd s1 means a write was in flight, even if s1 == s2\")\n\n\ndef isr_cpu_percent(wcet_us, period_us):\n    \"\"\"100 * WCET / T_pwm.\"\"\"\n    raise NotImplementedError(\"TODO 8: a percentage needs the multiply by 100\")\n\n\n# The browser entry appends `selfcheck.py` below this line; on its own this file prints nothing.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 04-embedded.T3.04a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert center_aligned_arr(170_000_000.0, 40_000.0) == 2125, \"up-down counts twice\"\n    assert center_aligned_arr(160_000_000.0, 25_000.0) == 3200, \"the exercise register\"\n    assert abs(pwm_frequency(170_000_000.0, 1700) - 50_000.0) < 1e-9, \"the Gate test carrier\"\n    checks += 1\n\n    assert abs(low_side_window_ns(0.88, 250.0, 40_000.0) - 2500.0) < 1e-9, \"two dead times\"\n    assert abs(low_side_window_ns(0.90, 200.0, 40_000.0) - 2100.0) < 1e-9, \"the Skip test window\"\n    checks += 1\n\n    assert q31_encode(0.5) == 1073741824, \"cos(pi/3) is exactly 2^30\"\n    assert angle_to_q31(math.pi / 3.0) == 715827883, \"theta/pi, then 2^31\"\n    assert q31_encode(-0.50) == -1073741824, \"the exercise word\"\n    assert q31_encode(1.0) == (1 << 31) - 1, \"+1.0 clamps, it does not wrap\"\n    assert abs(q31_decode(1073741824) - 0.5) < 1e-15, \"and decoding halves it back\"\n    checks += 1\n\n    assert seqlock_valid(4, 4) is True, \"a clean read\"\n    assert seqlock_valid(5, 5) is False, \"an odd snapshot is mid-write\"\n    assert seqlock_valid(4, 6) is False, \"the writer ran between s1 and s2\"\n    checks += 1\n\n    assert abs(isr_cpu_percent(3.0, 25.0) - 12.0) < 1e-12, \"3 us of 25 us is 12%\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the center-aligned ARR and its low-side window, the Q1.31 \"\n          \"word with its clamp, the even/odd sequence check, and the fast ISR's share of the CPU\"\n          % checks)\n\n\n_selfcheck()\n",
