    "fullSolution": "\"\"\"Exercise 06-robotics.T1.06a - reference solution.\n\nA rest-to-rest cubic: the four coefficients its boundary conditions pin down, the peak velocity it\ndemands, the duration an actuator's speed or acceleration budget allows, and the spring-damper plus\ngravity feedforward that tracks it and yields when a hand pushes.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef cubic_rest_to_rest(t, q0, qf, T):\n    \"\"\"(q, qd, qdd) at time t for a rest-to-rest cubic; clamped to the endpoints outside [0, T].\"\"\"\n    if T <= 0.0:\n        raise ValueError(\"a move needs a positive duration\")\n    if t > T:\n        return qf, 0.0, 0.0\n    s = min(1.0, max(0.0, t / T))\n    dq = qf - q0\n    q = q0 + dq * (3.0 * s * s - 2.0 * s * s * s)\n    qd = (6.0 * dq / T) * (s - s * s)\n    qdd = (6.0 * dq / (T * T)) * (1.0 - 2.0 * s)\n    return q, qd, qdd\n\n\ndef cubic_coefficients(q0, qf, T):\n    \"\"\"(a0, a1, a2, a3) of q(t) = a0 + a1 t + a2 t^2 + a3 t^3 with zero endpoint velocities.\"\"\"\n    if T <= 0.0:\n        raise ValueError(\"a move needs a positive duration\")\n    dq = qf - q0\n    return q0, 0.0, 3.0 * dq / (T * T), -2.0 * dq / (T * T * T)\n\n\ndef peak_velocity(dq, T):\n    \"\"\"Peak speed of a rest-to-rest cubic: 1.5 * dq / T.\"\"\"\n    if T <= 0.0:\n        raise ValueError(\"a move needs a positive duration\")\n    return 1.5 * dq / T\n\n\ndef min_duration_s(dq, qd_max):\n    \"\"\"Shortest move whose peak speed stays inside the actuator's limit.\"\"\"\n    if qd_max <= 0.0:\n        raise ValueError(\"a speed limit must be positive\")\n    return 1.5 * abs(dq) / qd_max\n\n\ndef min_duration_for_acceleration(dq, qdd_max):\n    \"\"\"Shortest move whose peak acceleration 6|dq|/T^2 stays inside the actuator's limit.\"\"\"\n    if qdd_max <= 0.0:\n        raise ValueError(\"an acceleration limit must be positive\")\n    return math.sqrt(6.0 * abs(dq) / qdd_max)\n\n\ndef spring_damper_torque(q_d, q, dq_d, dq, kp, kd, tau_g=0.0):\n    \"\"\"tau = kp (q_d - q) + kd (dq_d - dq) + tau_g.\"\"\"\n    if kp < 0.0 or kd < 0.0:\n        raise ValueError(\"stiffness and damping cannot be negative\")\n    return kp * (q_d - q) + kd * (dq_d - dq) + tau_g\n\n\ndef compliance_deflection(tau_ext, kp):\n    \"\"\"Steady yield under a hand push at rest: tau_ext / kp.\"\"\"\n    if kp <= 0.0:\n        raise ValueError(\"a spring needs positive stiffness\")\n    return tau_ext / kp\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 06-robotics.T1.06a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    q, qd, qdd = cubic_rest_to_rest(1.0, 0.0, 1.2, 2.0)\n    assert abs(q - 0.6) < 1e-12 and abs(qd - 0.9) < 1e-12 and abs(qdd) < 1e-12, \"the midpoint\"\n    assert abs(cubic_rest_to_rest(0.0, 0.0, 1.2, 2.0)[1]) < 1e-12, \"zero starting speed\"\n    assert abs(cubic_rest_to_rest(2.0, 0.0, 1.2, 2.0)[0] - 1.2) < 1e-12, \"the target is reached\"\n    assert abs(cubic_rest_to_rest(9.0, 0.0, 1.2, 2.0)[1]) < 1e-12, \"and held still after\"\n    checks += 1\n\n    a0, a1, a2, a3 = cubic_coefficients(0.3, 1.1, 1.6)\n    for t in (0.0, 0.4, 1.6):\n        poly = a0 + a1 * t + a2 * t * t + a3 * t ** 3\n        assert abs(poly - cubic_rest_to_rest(t, 0.3, 1.1, 1.6)[0]) < 1e-12, \"coefficients agree\"\n    assert abs(a1) < 1e-15 and abs(a1 + 2 * a2 * 1.6 + 3 * a3 * 1.6 ** 2) < 1e-12\n    checks += 1\n\n    assert abs(peak_velocity(2.0, 4.0) - 0.75) < 1e-12, \"peak speed\"\n    assert abs(min_duration_s(2.0, 3.0) - 1.0) < 1e-12, \"speed-limited duration\"\n    assert abs(min_duration_for_acceleration(2.0, 3.0) - 2.0) < 1e-12, \"acceleration limit\"\n    checks += 1\n\n    tau = spring_damper_torque(0.8, 0.7, 0.5, 0.2, 10.0, 1.0, 0.4)\n    assert abs(tau - 1.7) < 1e-12, \"the spring-damper plus gravity\"\n    assert abs(spring_damper_torque(0.4, 0.4, 0.0, 0.0, 8.0, 0.5, -1.2) + 1.2) < 1e-12\n    assert abs(compliance_deflection(0.50, 5.0) - 0.10) < 1e-12, \"the yield\"\n    assert compliance_deflection(0.5, 20.0) < compliance_deflection(0.5, 4.0)\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the rest-to-rest cubic, its coefficients, the peak speed and \"\n          \"both duration limits, the spring-damper and the compliance yield\" % checks)\n\n\n_selfcheck()\n",
