    "fullSolution": "\"\"\"Exercise 06-robotics.T2.06a - reference solution.\n\nA ROS 2 graph is a set of promises about who can talk to whom, and a tf2 tree is a product of\nhomogeneous transforms. The QoS rule is an inequality on each policy, not a match: a Best-Effort\npublisher cannot feed a Reliable subscriber. The transform chain is `T = Rz(q1) Trans(L1) Rz(q2)\nTrans(L2)`, whose translation is exactly the plant's forward kinematics.\n\"\"\"\n\nimport math\n\nimport mechalab_plant as plant  # noqa: F401  (kept so the submission imports what the module uses)\n\n\ndef qos_compatible(pub_reliable, pub_transient_local, sub_reliable, sub_transient_local):\n    \"\"\"`offered >= requested` on reliability and on durability, both of them.\"\"\"\n    reliable_ok = int(bool(pub_reliable)) >= int(bool(sub_reliable))\n    durability_ok = int(bool(pub_transient_local)) >= int(bool(sub_transient_local))\n    return reliable_ok and durability_ok\n\n\ndef urdf_revolute_z(xyz, q_rad):\n    \"\"\"A revolute joint about +Z with its origin offset: `[Rz(q), xyz; 0, 1]`.\"\"\"\n    c = math.cos(q_rad)\n    s = math.sin(q_rad)\n    return [[c, -s, 0.0, xyz[0]],\n            [s, c, 0.0, xyz[1]],\n            [0.0, 0.0, 1.0, xyz[2]],\n            [0.0, 0.0, 0.0, 1.0]]\n\n\ndef mat4_mul(a, b):\n    \"\"\"Product of two 4x4 homogeneous transforms.\"\"\"\n    return [[sum(a[i][k] * b[k][j] for k in range(4)) for j in range(4)] for i in range(4)]\n\n\ndef transform_point(t, p):\n    \"\"\"Apply a homogeneous transform to a 3-vector (the homogeneous 1 is implicit).\"\"\"\n    return [sum(t[i][j] * p[j] for j in range(3)) + t[i][3] for i in range(3)]\n\n\ndef invert_rigid(t):\n    \"\"\"Inverse of a rigid transform: `R^T` and `-R^T p`, never a general 4x4 inverse.\"\"\"\n    r_t = [[t[j][i] for j in range(3)] for i in range(3)]\n    inverse = [[r_t[i][0], r_t[i][1], r_t[i][2],\n                -(r_t[i][0] * t[0][3] + r_t[i][1] * t[1][3] + r_t[i][2] * t[2][3])]\n               for i in range(3)]\n    inverse.append([0.0, 0.0, 0.0, 1.0])\n    return inverse\n\n\ndef interpolate(t_a, value_a, t_b, value_b, t_query):\n    \"\"\"Linear interpolation in time; a query outside the buffer is refused, as tf2 refuses it.\"\"\"\n    if t_b == t_a:\n        raise ValueError(\"the buffer's two stamps must differ\")\n    if t_query < min(t_a, t_b) or t_query > max(t_a, t_b):\n        raise ValueError(\"extrapolation: %.6f is outside [%.6f, %.6f]\" % (t_query, t_a, t_b))\n    alpha = (t_query - t_a) / (t_b - t_a)\n    return (1.0 - alpha) * value_a + alpha * value_b\n\n\ndef topic_bandwidth_mb_s(n_subs, size_bytes, rate_hz):\n    \"\"\"Unicast bandwidth to `n_subs` subscribers, in MB/s.\"\"\"\n    return n_subs * size_bytes * rate_hz / 1e6\n\n\n# No `__main__` block on purpose: the browser grades this file's stdout against the appended\n# self-check's single PASS line, and a second print here would be a mismatch for a correct answer.\n\n\n# --- browser self-check, appended by scripts/exercise_bundle.py; do not edit here ---\n\"\"\"Browser self-check for 06-robotics.T2.06a.\n\nAppended verbatim to the workbench entry, after the learner's code. Stdlib-only, one PASS line.\n\"\"\"\n\nimport math\n\n\ndef _selfcheck():\n    checks = 0\n\n    assert qos_compatible(True, True, True, True) is True, \"a match connects\"\n    assert qos_compatible(True, False, False, False) is True, \"reliable feeds best-effort\"\n    assert qos_compatible(False, False, True, False) is False, \"best-effort cannot feed reliable\"\n    assert qos_compatible(True, False, True, True) is False, \"volatile cannot feed transient local\"\n    checks += 1\n\n    t = urdf_revolute_z((0.25, 0.0, 0.10), 0.0)\n    assert t[0] == [1.0, 0.0, 0.0, 0.25], \"a zero joint is a translation\"\n    assert t[3] == [0.0, 0.0, 0.0, 1.0], \"homogeneous bottom row\"\n    checks += 1\n\n    turn = urdf_revolute_z((0.0, 0.0, 0.0), math.pi / 2.0)\n    out = transform_point(turn, [1.0, 0.0, 0.0])\n    assert abs(out[0]) < 1e-12 and abs(out[1] - 1.0) < 1e-12, \"a quarter turn about +Z\"\n    checks += 1\n\n    t_b_l1 = urdf_revolute_z((0.0, 0.0, 0.10), 0.0)\n    t_l1_tool = urdf_revolute_z((0.25, 0.0, 0.0), math.pi / 2.0)\n    p = transform_point(mat4_mul(t_b_l1, t_l1_tool), [0.15, 0.0, 0.0])\n    assert abs(p[0] - 0.25) < 1e-9 and abs(p[1] - 0.15) < 1e-9 and abs(p[2] - 0.10) < 1e-9\n    checks += 1\n\n    pose = mat4_mul(urdf_revolute_z((0.3, -0.2, 0.1), 0.9), urdf_revolute_z((0.1, 0.0, 0.0), -1.4))\n    target = [0.05, -0.07, 0.02]\n    back = transform_point(invert_rigid(pose), transform_point(pose, target))\n    assert all(abs(back[i] - target[i]) < 1e-12 for i in range(3)), \"the rigid inverse round-trips\"\n    checks += 1\n\n    assert abs(interpolate(1.000, 0.20, 1.010, 0.25, 1.004) - 0.22) < 1e-9, \"buffer interpolation\"\n    assert abs(interpolate(2.0, 7.0, 3.0, 9.0, 3.0) - 9.0) < 1e-12, \"the end is the sample\"\n    try:\n        interpolate(1.0, 0.0, 1.1, 1.0, 1.2)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError(\"extrapolation must be refused\")\n    checks += 1\n\n    assert abs(topic_bandwidth_mb_s(3, 1200, 30.0) - 0.108) < 1e-12, \"unicast bandwidth\"\n    assert topic_bandwidth_mb_s(0, 5000, 100.0) == 0.0, \"no subscribers, no traffic\"\n    checks += 1\n\n    print(\"SELF-CHECK PASS: %d checks - the QoS rule, a joint matrix, a quarter turn, the tf2 \"\n          \"chain, the rigid inverse, the buffer interpolation and the bandwidth budget\" % checks)\n\n\n_selfcheck()\n",
